// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ValidationTask) predicate.ValidationTask {
	return predicate.ValidationTask(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ValidationTask) predicate.ValidationTask {
	return predicate.ValidationTask(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ValidationTask) predicate.ValidationTask {
	return predicate.ValidationTask(sql.NotPredicates(p))
}
